import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../store/slice/reducer';

function StepOne({ next }) {
  const dispatch = useDispatch();
  const firstName = useSelector(state => state.firstName);
  const lastName = useSelector(state => state.lastName);
  const email = useSelector(state => state.email);

  return (
    <>
      <h4>Step 1: User Info</h4>
      <input className="form-control my-2" placeholder="First Name" value={firstName}
        onChange={(e) => dispatch(updateField({ field: 'firstName', value: e.target.value }))} />
      <input className="form-control my-2" placeholder="Last Name" value={lastName}
        onChange={(e) => dispatch(updateField({ field: 'lastName', value: e.target.value }))} />
      <input className="form-control my-2" placeholder="Email" value={email}
        onChange={(e) => dispatch(updateField({ field: 'email', value: e.target.value }))} />
      <button className="btn btn-primary mt-2" onClick={next}>Next →</button>
    </>
  );
}

export default StepOne;
